# Public API (cm:*)
  @api cm:setContext(newTake)  @ 421-426
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 419
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 420
  @api cm:clearTake()  @ 428-433
  @api cm:boundTake()  @ 436
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 435
  @api cm:boundTrack()  @ 439
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 438
  @api cm:setTrack(newTrack)  @ 441-446
  @api cm:pollUndo()  @ 449
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 448
  @api cm:isDeclared(key)  @ 486
      @contract  non-raising existence test against the schema; true iff key is declared  @ 485
  @api cm:get(key, opts)  @ 493-500
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 503-512
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 502
  @api cm:valueFor(handle, scope, key)  @ 515-522
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 514
  @api cm:defaultFor(key)  @ 525-528
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 524
  -- Writing
  @api cm:set(level, key, value)  @ 533-543
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 532
  @api cm:remove(level, key)  @ 546-557
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 545
  @api cm:assign(level, updates)  @ 560-574
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 559

